{
  "name": "swarmery-link",
  "description": "Mod (function hooks): reports this session's live state (turn start and end, tool calls by name and input hash, context fill, rate limits, cost) to a local swarmery daemon over its token-guarded link API, and switches itself off when the daemon's token file is absent. The sensor never blocks, changes or answers a hook's event. With the opt-in control option it also long-polls the daemon for this session's commands: stop aborts the running turn, prompt submits a prompt once the session is idle. With the opt-in forecast option it asks a small model, once per user turn and without holding the turn, what the turn will touch, and reports the forecast beside the actual (paths and numbers only) so the daemon can score its surprise.",
  "version": "0.3.0",
  "author": {
    "name": "atretyak",
    "email": "atretiak.work@gmail.com"
  },
  "keywords": [
    "sensor",
    "telemetry",
    "dashboard",
    "remote-control",
    "forecast",
    "mods"
  ],
  "userConfig": {
    "control": {
      "type": "boolean",
      "title": "Control from the dashboard",
      "description": "Let the swarmery dashboard stop this session's running turn and send it prompts. One background loop long-polls the daemon (loopback only, bearer token) for commands queued for this session alone; nothing runs inside a hook and no gating hook is registered. Off: no request goes to the command endpoints.",
      "default": false
    },
    "planBand": {
